import React, { useEffect, useState } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import { eventAPI } from '../../utils/api';
import './StudentEvents.css';

const NAV_ITEMS = [
  { path: '/student', label: 'Dashboard', icon: '🏠', end: true },
  { path: '/student/submit', label: 'Submit Request', icon: '➕' },
  { path: '/student/requests', label: 'My Requests', icon: '📋' },
  { path: '/student/events', label: 'Events', icon: '📅' },
  { path: '/student/policies', label: 'Policies', icon: '📚' },
  { path: '/student/profile', label: 'Profile', icon: '👤' },
];

const CATEGORY_OPTIONS = ['', 'academic', 'club', 'placement', 'admin'];

export default function StudentEvents() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [category, setCategory] = useState('');
  const [search, setSearch] = useState('');
  const [registeringId, setRegisteringId] = useState('');

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const data = await eventAPI.getEvents({ category, search, upcoming: true });
      setEvents(data);
      setError('');
    } catch (requestError) {
      setError(requestError.message || 'Failed to load events');
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchEvents();
  }, [category, search]);

  const handleRegister = async (eventId) => {
    setRegisteringId(eventId);
    try {
      await eventAPI.registerForEvent(eventId);
      await fetchEvents();
      setError('');
    } catch (requestError) {
      setError(requestError.message || 'Failed to register for event');
    }
    setRegisteringId('');
  };

  return (
    <DashboardLayout navItems={NAV_ITEMS}>
      <div className="page-header">
        <h1 className="page-title">Upcoming Events</h1>
        <p className="page-subtitle">Register for academic, club, placement, and administrative events.</p>
      </div>

      {error && <div className="alert alert-error">❌ {error}</div>}

      <div className="card event-filter-card">
        <input
          className="form-input"
          placeholder="Search by title or location..."
          value={search}
          onChange={(event) => setSearch(event.target.value)}
        />
        <select className="form-select" value={category} onChange={(event) => setCategory(event.target.value)}>
          {CATEGORY_OPTIONS.map((option) => (
            <option key={option || 'all'} value={option}>
              {option ? option[0].toUpperCase() + option.slice(1) : 'All categories'}
            </option>
          ))}
        </select>
      </div>

      {loading ? (
        <div className="card">
          <div className="empty-state">
            <div className="spinner" style={{ marginBottom: 16 }} />
            <h3>Loading events...</h3>
          </div>
        </div>
      ) : events.length === 0 ? (
        <div className="card">
          <div className="empty-state">
            <h3>No upcoming events found</h3>
          </div>
        </div>
      ) : (
        <div className="event-grid">
          {events.map((event) => (
            <div key={event._id} className="card event-card">
              {event.poster?.url && (
                <img
                  src={event.poster.url}
                  alt={`${event.title} poster`}
                  className="event-poster-image"
                />
              )}
              <div className="event-card-header">
                <div className="event-category">{event.category}</div>
                <div className="event-status">{event.status}</div>
              </div>
              <h3 className="event-title">{event.title}</h3>
              <p className="event-description">{event.description}</p>
              <div className="event-meta">📍 {event.location}</div>
              <div className="event-meta">🕒 {new Date(event.startAt).toLocaleString('en-GB')}</div>
              <div className="event-meta">
                👥 {event.attendeeCount}/{event.capacity} registered
              </div>
              <div className="event-meta">
                ⏱ Seats left: {event.seatsAvailable}
              </div>
              {event.registrationDeadline && (
                <div className="event-meta">
                  Registration closes: {new Date(event.registrationDeadline).toLocaleString('en-GB')}
                </div>
              )}
              <div className="event-actions">
                <button
                  className="btn btn-primary btn-sm"
                  onClick={() => handleRegister(event._id)}
                  disabled={event.isRegistered || registeringId === event._id || event.seatsAvailable <= 0}
                >
                  {event.isRegistered ? 'Registered' : registeringId === event._id ? 'Registering...' : 'Register'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </DashboardLayout>
  );
}
